import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Supabase Free Plan limits
const LIMITS = {
  db_size_mb: 500,           // 500 MB database
  storage_size_mb: 1000,     // 1 GB storage
  users: 50000,              // 50k MAU
  edge_invocations: 500000,  // 500k/month
  realtime_connections: 200, // concurrent
};

// Alert thresholds (percentage)
const WARN_THRESHOLD = 75;
const CRITICAL_THRESHOLD = 90;

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  // Version check
  const debugParam = new URL(req.url).searchParams.get('debug');
  if (debugParam === 'ping') {
    return new Response(JSON.stringify({ ok: true, version: 10 }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';

    // Auth: try JWT decode first, fallback to getUser
    const authHeader = req.headers.get('Authorization') || '';
    const token = authHeader.replace('Bearer ', '');
    let userId = '';

    // Decode JWT payload (Supabase gateway already verified signature)
    let decodeError = '';
    if (token && token.includes('.')) {
      try {
        let b64 = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
        while (b64.length % 4) b64 += '=';
        const payload = JSON.parse(atob(b64));
        userId = payload.sub || '';
      } catch (e) {
        decodeError = (e as Error).message;
      }
    }

    if (!userId) {
      return new Response(JSON.stringify({
        error: 'Unauthorized',
        debug: {
          hasAuth: !!authHeader,
          authStart: authHeader.substring(0, 20),
          tokenLen: token.length,
          hasDot: token.includes('.'),
          decodeError,
        }
      }), {
        status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // Only allow the owner
    const OWNER_ID = 'ef8fbade-5ef0-48b7-9cb1-6792bb956baa';
    if (userId !== OWNER_ID) {
      return new Response(JSON.stringify({ error: 'Forbidden', userId }), {
        status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // Service role client for querying all tables
    const supabase = createClient(supabaseUrl, serviceKey);

    // ── 1. Database size ──
    const { data: dbSize } = await supabase.rpc('get_db_size');
    const dbSizeMb = dbSize ? parseFloat(dbSize) : 0;

    // ── 2. Table row counts ──
    const tables = ['profiles', 'reviews', 'restaurants', 'notifications', 'comments',
                     'likes', 'bookmarks', 'reports', 'user_settings', 'food_detections'];
    const tableCounts: Record<string, number> = {};
    for (const table of tables) {
      const { count } = await supabase.from(table).select('*', { count: 'exact', head: true });
      tableCounts[table] = count ?? 0;
    }

    // ── 3. Storage usage (real, summed from storage.objects metadata) ──
    // Use a SECURITY DEFINER RPC so we can read storage.objects without
    // needing service role to bypass RLS in the SQL editor sense.
    const { data: storageBytesData } = await supabase.rpc('get_storage_total_bytes');
    const storageMb = storageBytesData ? (Number(storageBytesData) / 1024 / 1024) : 0;

    // ── 4. Users count ──
    const totalUsers = tableCounts['profiles'] || 0;

    // ── 5. Edge function invocations this month ──
    // Sum of every function's real proxy:
    //   detect-food     ≈ count(food_detections)
    //   apply-referral  ≈ count(referrals)
    //   notify          ≈ count(notifications WHERE type IN like/bookmark)
    //   check-quotas    ≈ negligible (a handful of admin opens)
    //   cleanup         ≈ 1 per day (cron)
    //   analytics-backup≈ 1 per hour (cron)
    const startOfMonth = new Date();
    startOfMonth.setDate(1);
    startOfMonth.setHours(0, 0, 0, 0);
    const daysSinceMonthStart = Math.max(1, Math.ceil(
      (Date.now() - startOfMonth.getTime()) / 86400000,
    ));
    const hoursSinceMonthStart = daysSinceMonthStart * 24;

    const { count: detectionsThisMonth } = await supabase
      .from('food_detections')
      .select('*', { count: 'exact', head: true })
      .gte('created_at', startOfMonth.toISOString());
    const { count: referralsThisMonth } = await supabase
      .from('referrals')
      .select('*', { count: 'exact', head: true })
      .gte('created_at', startOfMonth.toISOString());
    const { count: notifyTriggeredThisMonth } = await supabase
      .from('notifications')
      .select('*', { count: 'exact', head: true })
      .in('type', ['like', 'bookmark'])
      .gte('created_at', startOfMonth.toISOString());

    const edgeInvocationsThisMonth = (detectionsThisMonth ?? 0)
      + (referralsThisMonth ?? 0)
      + (notifyTriggeredThisMonth ?? 0)
      + daysSinceMonthStart           // cleanup cron
      + hoursSinceMonthStart;         // analytics-backup cron

    // ── 6. Google API usage (real, not estimated) ──
    // Each successful getPlaceDetails call writes restaurants.google_rating_updated_at
    // (cf. useGoogleRating.ts and useRestaurants.ts createRestaurant flow).
    // Counting rows updated this month gives us the real number of placeDetails
    // calls served. Geocoding does NOT use Google (Nominatim/Photon), so it
    // doesn't count.
    const { count: placeDetailsThisMonth } = await supabase
      .from('restaurants')
      .select('*', { count: 'exact', head: true })
      .gte('google_rating_updated_at', startOfMonth.toISOString());

    // findPlace overhead: when a restaurant is created from OSM, the app fires
    // one findPlace then one placeDetails. We can't track findPlace timestamps
    // directly, but every restaurant created this month with a real Google
    // place_id (not osm_*) implies one extra findPlace call.
    const { count: newGooglePlaceIdsThisMonth } = await supabase
      .from('restaurants')
      .select('*', { count: 'exact', head: true })
      .gte('created_at', startOfMonth.toISOString())
      .not('google_place_id', 'is', null)
      .not('google_place_id', 'like', 'osm_%');

    const realGoogleCalls = (placeDetailsThisMonth ?? 0) + (newGooglePlaceIdsThisMonth ?? 0);

    // Note: Storage bandwidth (egress) is removed from this dashboard
    // because it cannot be measured from the database alone — it requires
    // the Supabase Analytics API which we don't query here. The "Stockage
    // photos" quota above tracks what matters for the free tier (1 GB).

    // ── Build quotas ──
    const quotas = [
      {
        id: 'db_size',
        label: 'Base de données',
        used: dbSizeMb,
        limit: LIMITS.db_size_mb,
        unit: 'MB',
        percentage: (dbSizeMb / LIMITS.db_size_mb) * 100,
      },
      {
        id: 'storage',
        label: 'Stockage photos',
        used: Math.round(storageMb * 10) / 10,
        limit: LIMITS.storage_size_mb,
        unit: 'MB',
        percentage: (storageMb / LIMITS.storage_size_mb) * 100,
      },
      {
        id: 'users',
        label: 'Utilisateurs',
        used: totalUsers,
        limit: LIMITS.users,
        unit: '',
        percentage: (totalUsers / LIMITS.users) * 100,
      },
      {
        id: 'edge_functions',
        label: 'Edge Functions (ce mois)',
        used: edgeInvocationsThisMonth,
        limit: LIMITS.edge_invocations,
        unit: 'appels',
        percentage: (edgeInvocationsThisMonth / LIMITS.edge_invocations) * 100,
      },
      {
        id: 'google_api',
        label: 'Google API (ce mois)',
        used: realGoogleCalls,
        limit: 40000, // $200 free credit ÷ $5/1000 (Basic SKU) = 40,000 calls
        unit: 'appels',
        percentage: (realGoogleCalls / 40000) * 100,
      },
      {
        id: 'huggingface',
        label: 'Hugging Face IA (ce mois)',
        used: detectionsThisMonth ?? 0,
        limit: 30000, // HF free tier ~30k/month
        unit: 'appels',
        percentage: ((detectionsThisMonth ?? 0) / 30000) * 100,
      },
    ];

    // ── Alerts ──
    const alerts = quotas
      .filter((q) => q.percentage >= WARN_THRESHOLD)
      .map((q) => ({
        id: q.id,
        label: q.label,
        percentage: Math.round(q.percentage),
        level: q.percentage >= CRITICAL_THRESHOLD ? 'critical' : 'warning',
      }));

    return new Response(
      JSON.stringify({
        quotas,
        alerts,
        tableCounts,
        timestamp: new Date().toISOString(),
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    return new Response(
      JSON.stringify({ error: (err as Error).message }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});
